export type MessageConcept = keyof typeof messages;

/** Finite dynamic concept selection only; IDs are always generated by Lingui. */
export function messageForKey(key: MessageConcept): MessageDescriptor {
const descriptor = messages[key];
if (!descriptor) throw new Error(`Unknown message concept: ${key}`);
return descriptor;
}
